    }
    const y0 = Math.floor(sourceY);
    const y1 = y0 + 1;
    const yWeight = sourceY - y0;
    for (let x = 0; x < destinationWidth; x += 1) {
      const sourceX = sourceCoordinate(x, sourceWidth, destinationWidth);
      const x0 = Math.floor(sourceX);
      const x1 = x0 + 1;
      const xWeight = sourceX - x0;
