      destinationHeight - 1,
      Math.ceil(((tile.y + tile.height) * destinationHeight) / sourceHeight) + 1,
    );
    for (
      let row = Math.floor(top / destinationTileSize);
      row <= Math.floor(bottom / destinationTileSize);
      row += 1
