        strokeBounds.left,
        Math.floor(localDest.x - radius),
      );
      strokeBounds.top = Math.min(
        strokeBounds.top,
        Math.floor(localDest.y - radius),
      );
      strokeBounds.right = Math.max(
        strokeBounds.right,
        Math.ceil(localDest.x + radius),
