          x: sourceDocPoint.x + source.offset.x,
          y: sourceDocPoint.y + source.offset.y,
        };
      }
    } else {
      // Aligned: destination + offset (or destination if no offset)
      sourceDocPoint = { ...destDocPoint };
      if (source.offset !== null) {
        sourceDocPoint = {
          x: sourceDocPoint.x + source.offset.x,
          y: sourceDocPoint.y + source.offset.y,
        };
      }
    }

    // Convert to layer-local coordinates
    const localDest = applyInverseTransform(
      effectiveDestinationTransform,
      destDocPoint.x,
      destDocPoint.y,
    );
    const localSrc = applyInverseTransform(
      effectiveSourceTransform,
      sourceDocPoint.x,
      sourceDocPoint.y,
    );

    // Check source bounds
    if (
      localSrc.x < 0 ||
      localSrc.y < 0 ||
      localSrc.x >= sourceLayer.width ||
      localSrc.y >= sourceLayer.height
    ) {
      continue;
    }

    // Sample source color at this dab's source location
    const sourcePixels = sourceLayer.pixelStore.read({
      x: Math.round(localSrc.x),
      y: Math.round(localSrc.y),
      width: 1,
      height: 1,
    });
    const sampledColor: [number, number, number, number] = [
      sourcePixels[0],
      sourcePixels[1],
      sourcePixels[2],
      sourcePixels[3],
    ];

    // Paint this dab using the sampled color
    const patch = paintSingleDab(
      destinationLayer,
      pixels,
      strokeBounds,
      regionWidth,
      regionHeight,
      localDest,
      radius,
      hardness,
      opacity,
      dab.pressure,
      sampledColor,
      selection,
      effectiveDestinationTransform,
    );

    if (patch.changedBounds) {
      changedBounds = unionBounds(changedBounds, patch.changedBounds);
    }
  }

  if (!changedBounds) {
    return emptyPatch();
  }

  // Extract the changed region from the working pixels
  const patchLeft = Math.max(strokeBounds.left, changedBounds.left);
  const patchTop = Math.max(strokeBounds.top, changedBounds.top);
  const patchRight = Math.min(
    strokeBounds.left + regionWidth - 1,
    changedBounds.right,
  );
  const patchBottom = Math.min(
    strokeBounds.top + regionHeight - 1,
    changedBounds.bottom,
  );

  const patchWidth = patchRight - patchLeft + 1;
  const patchHeight = patchBottom - patchTop + 1;
  const patchPixels = new Uint8ClampedArray(patchWidth * patchHeight * 4);

  for (let y = patchTop; y <= patchBottom; y++) {
    for (let x = patchLeft; x <= patchRight; x++) {
      const srcOffset =
        ((y - strokeBounds.top) * regionWidth + (x - strokeBounds.left)) * 4;
      const dstOffset = ((y - patchTop) * patchWidth + (x - patchLeft)) * 4;
      patchPixels[dstOffset] = pixels[srcOffset];
      patchPixels[dstOffset + 1] = pixels[srcOffset + 1];
      patchPixels[dstOffset + 2] = pixels[srcOffset + 2];
      patchPixels[dstOffset + 3] = pixels[srcOffset + 3];
    }
  }

  return {
    x: patchLeft,
    y: patchTop,
    width: patchWidth,
    height: patchHeight,
    pixels: patchPixels,
  };
}

interface DabResult {
  changedBounds: {
    left: number;
    top: number;
    right: number;
    bottom: number;
  } | null;
}

function paintSingleDab(
  destinationLayer: PixelLayer,
  pixels: Uint8ClampedArray,
  strokeBounds: {
    left: number;
    top: number;
    right: number;
    bottom: number;
  },
  regionWidth: number,
  regionHeight: number,
  localDest: { x: number; y: number },
  radius: number,
  hardness: number,
  opacity: number,
  pressure: number,
  color: [number, number, number, number],
  selection: SelectionMask | null,
  worldTransform: LayerTransform,
): DabResult {
  const changedBounds: {
    left: number;
    top: number;
    right: number;
    bottom: number;
  } | null = null;

  // Iterate over pixels in the dab's influence region
  const startX = Math.max(
    strokeBounds.left,
    Math.floor(localDest.x - radius),
  );
  const startY = Math.max(
    strokeBounds.top,
    Math.floor(localDest.y - radius),
  );
  const endX = Math.min(
    strokeBounds.left + regionWidth - 1,
    Math.ceil(localDest.x + radius),
  );
  const endY = Math.min(
    strokeBounds.top + regionHeight - 1,
    Math.ceil(localDest.y + radius),
  );

  for (let y = startY; y <= endY; y++) {
    for (let x = startX; x <= endX; x++) {
      // Convert to document space
      const docPoint = applyTransform(worldTransform, x, y);

      // Calculate distance from dab center in document space
      const dx = docPoint.x - localDest.x;
      const dy = docPoint.y - localDest.y;
      const distance = Math.sqrt(dx * dx + dy * dy);

      if (distance > radius) continue;

      // Calculate falloff based on hardness
      let falloff = 1;
      if (hardness < 1) {
        const hardRadius = radius * hardness;
        if (distance > hardRadius) {
          falloff = 1 - (distance - hardRadius) / (radius - hardRadius);
        }
      }

      // Check selection
      let selected = 1;
      if (selection) {
        const selX = Math.round(docPoint.x);
        const selY = Math.round(docPoint.y);
        if (
          selX >= 0 &&
          selX < selection.width &&
          selY >= 0 &&
          selY < selection.height
        ) {
          const coverage = selection.coverageStore.read({
            x: selX,
            y: selY,
            width: 1,
            height: 1,
          })[0];
          selected = coverage / 255;
        } else {
          selected = 0;
        }
      }

      const strength = falloff * opacity * pressure * selected;
      if (strength <= 0) continue;

      // Apply source-over compositing
      const pixelOffset =
        ((y - strokeBounds.top) * regionWidth + (x - strokeBounds.left)) * 4;
      const srcAlpha = (color[3] / 255) * strength;
      const dstAlpha = pixels[pixelOffset + 3] / 255;
      const outAlpha = srcAlpha + dstAlpha * (1 - srcAlpha);

      if (outAlpha === 0) continue;

      const srcR = color[0];
      const srcG = color[1];
      const srcB = color[2];
      const dstR = pixels[pixelOffset];
      const dstG = pixels[pixelOffset + 1];
      const dstB = pixels[pixelOffset + 2];

      pixels[pixelOffset] = Math.round(
        (srcR * srcAlpha + dstR * dstAlpha * (1 - srcAlpha)) / outAlpha,
      );
      pixels[pixelOffset + 1] = Math.round(
        (srcG * srcAlpha + dstG * dstAlpha * (1 - srcAlpha)) / outAlpha,
      );
      pixels[pixelOffset + 2] = Math.round(
        (srcB * srcAlpha + dstB * dstAlpha * (1 - srcAlpha)) / outAlpha,
      );
      pixels[pixelOffset + 3] = Math.round(outAlpha * 255);

      if (changedBounds) {
        changedBounds.left = Math.min(changedBounds.left, x);
        changedBounds.top = Math.min(changedBounds.top, y);
        changedBounds.right = Math.max(changedBounds.right, x);
        changedBounds.bottom = Math.max(changedBounds.bottom, y);
      } else {
        changedBounds = { left: x, top: y, right: x, bottom: y };
      }
    }
  }

  return { changedBounds };
}

function applyTransform(
  transform: LayerTransform,
  x: number,
  y: number,
): { x: number; y: number } {
  return {
    x: transform.a * x + transform.c * y + transform.e,
    y: transform.b * x + transform.d * y + transform.f,
  };
}

function applyInverseTransform(
  transform: LayerTransform,
  x: number,
  y: number,
): { x: number; y: number } {
  const det = transform.a * transform.d - transform.b * transform.c;
  if (det === 0) {
    throw new RangeError('Transform is not invertible');
  }
  return {
    x:
      (transform.d * (x - transform.e) - transform.c * (y - transform.f)) / det,
    y:
      (-transform.b * (x - transform.e) + transform.a * (y - transform.f)) /
        det,
  };
}

function unionBounds(
  a: {
    left: number;
    top: number;
    right: number;
    bottom: number;
  } | null,
  b: {
    left: number;
    top: number;
    right: number;
    bottom: number;
  } | null,
): {
  left: number;
  top: number;
  right: number;
  bottom: number;
} | null {
  if (!a) return b;
  if (!b) return a;
  return {
    left: Math.min(a.left, b.left),
    top: Math.min(a.top, b.top),
    right: Math.max(a.right, b.right),
    bottom: Math.max(a.bottom, b.bottom),
  };
}

function emptyPatch(): PixelPatch {
  return {
    x: 0,
    y: 0,
    width: 0,
    height: 0,
    pixels: new Uint8ClampedArray(0),
  };
}

/**
 * Command that applies a clone stamp stroke as an atomic undoable operation.
 */
export function paintCloneStampCommand(
  document: {
    id: string;
    layers: readonly PixelLayer[];
  },
  destinationLayerId: string,
  sourceLayerId: string,
  points: readonly BrushPoint[],
  options: CloneStampOptions,
  selection?: SelectionMask | null,
): PixelPatch {
  // This will be used by the App to execute clone stamp as a command
  const destinationLayer = findLayer(
    document as any,
    destinationLayerId,
  ) as PixelLayer;
  const sourceLayer = findLayer(document as any, sourceLayerId) as PixelLayer;

  if (!destinationLayer || !sourceLayer) {
    throw new RangeError('Layer not found');
  }

  return paintCloneStamp(
    destinationLayer,
    sourceLayer,
    points,
    options,
    selection,
  );
}

