    ).toThrow('Layer transform must be invertible');
    expect(() =>
      paintMaskStroke(mask, identity, [{ x: 0, y: 0 }], {
        ...revealMaskBrush,
        opacity: 2,
      }),
    ).toThrow('Mask brush opacity must be between 0 and 1');
    expect(() =>
      paintMaskStroke(
        { ...mask, coverageStore: TiledCoverageStore.empty(2, 1) },
        identity,
        [{ x: 0, y: 0 }],
