    const noOp = paintMaskStroke(mask, identity, [{ x: 0, y: 0 }], {
      ...revealMaskBrush,
      size: 0,
    });

    expect(Array.from(patch.coverage)).toEqual([64]);
    expect(noOp).toEqual({
      x: 0,
      y: 0,
      width: 0,
      height: 0,
      coverage: new Uint8ClampedArray(),
    });
  });

