    const revealed = paintMaskStroke(mask, identity, [{ x: 0, y: 0 }], revealMaskBrush);
    const concealed = paintMaskStroke(mask, identity, [{ x: 1, y: 0 }], {
      ...revealMaskBrush,
      mode: 'conceal',
