                  className="action-button"
                  key={operation}
                  onClick={() => props.onRefineSelection(operation)}
                >
                  {operation[0]?.toUpperCase()}
                  {operation.slice(1)}
                </button>
              ))}
            </div>
          )}
        </>
      )}
      {props.tool === 'crop' && (
        <div className="option-group crop-options" aria-label="Crop options">
          {(['x', 'y', 'width', 'height'] as const).map((key) => (
            <label key={key}>
              {key === 'x' ? 'X' : key === 'y' ? 'Y' : key === 'width' ? 'W' : 'H'}
              <input
                type="number"
                step="1"
                min={key === 'width' || key === 'height' ? 1 : undefined}
                aria-label={`Crop ${key}`}
                value={props.cropRectangle?.[key] ?? ''}
                disabled={!props.cropRectangle}
                onChange={(event) => {
                  if (!props.cropRectangle) return;
                  const value = Math.round(Number(event.target.value));
                  if (!Number.isFinite(value)) return;
                  props.onCropRectangleChange({
                    ...props.cropRectangle,
                    [key]: key === 'width' || key === 'height' ? Math.max(1, value) : value,
                  });
                }}
                onKeyDown={(event) => {
                  if (event.key === 'Enter') {
                    event.preventDefault();
                    props.onApplyCrop();
                  } else if (event.key === 'Escape') {
                    event.preventDefault();
                    props.onCancelCrop();
                  }
                }}
              />
            </label>
          ))}
          <button
            className="action-button primary"
            disabled={!props.cropRectangle}
            onClick={props.onApplyCrop}
          >
            Apply crop
          </button>
          <button
            className="action-button"
            disabled={!props.cropRectangle}
            onClick={props.onCancelCrop}
          >
            Cancel crop
          </button>
        </div>
      )}
      {props.tool === 'transform' && (
        <span className="transform-instructions" role="status">
          Drag square handles to scale and the round handle to rotate. Hold Shift for uniform
          scaling; Escape cancels the active gesture.
        </span>
      )}
      {props.tool === 'cloneStamp' && (
        <div className="option-group" aria-label="Clone stamp options">
          <div className="clone-options">
            <label className="inline-check">
              <input
                type="checkbox"
                checked={props.cloneSource.alive}
                disabled={!props.documentOpen || !props.cloneSource.alive}
                onChange={(event) =>
                  props.onCloneSourceChange(
                    event.currentTarget.checked
                      ? props.cloneSource
                      : { ...props.cloneSource, alive: false },
                  )
                }
              />
              Source active
            </label>
            {props.cloneSource.alive && (
              <>
                <button
                  className="action-button"
                  onClick={() => {
                    props.setCanvasPointer('source');
                    props.onCloneSourceChange(
                      { ...props.cloneSource, view: 'source' },
