          max="400"
          value={Math.round(props.zoom * 100)}
          disabled={!props.documentOpen}
          onChange={(event) => props.onZoomChange(Number(event.target.value) / 100)}
        />
        <span>{Math.round(props.zoom * 100)}%</span>
      </div>
