import { useEffect, useRef, useState } from 'react';
import type { CloneSource, CloneStampOptions, DocumentPoint, LayerTransform } from '@freetoshop/raster-engine';

export function useCloneStampState(document: ReturnType<typeof createDocument> | null) {
  const [source, setSource] = useState<CloneSource | null>(null);
  const [aligned, setAligned] = useState(false);

  const updateSource = (newSource: CloneSource | null) => {
    setSource(newSource);
    if (newSource !== null) {
      setAligned(newSource.aligned);
    }
  };

  const updateAlign = (value: boolean) => {
    setAligned(value);
    setSource(prev => prev ? { ...prev, aligned: value } : null);
  };

  return {
    source,
    aligned,
    updateSource,
    updateAlign,
  };
}

