                aria-label="Magic Wand tolerance"
                type="range"
                min="0"
                max="255"
                value={props.wandTolerance}
                onChange={(event) => props.onWandToleranceChange(Number(event.target.value))}
              />
              <span>{props.wandTolerance}</span>
